def reserve(stock, orders):
    remaining = dict(stock)
    outcomes = []
    for order in orders:
        accepted = True
        for sku, quantity in order["items"]:
            if remaining[sku] < quantity:
                accepted = False
                break
            remaining[sku] -= quantity
        outcomes.append({"order_id": order["id"], "accepted": accepted})
    return remaining, outcomes
